mapper.select:
/* selectMasterMdCpAgntcmpyList */ SELECT A.COM_NAME_LOC, A.CM_STATUS, A.STATUS, A.IRS_NO, A.WEB_LINK_KCB, A.WEB_LINK_KCB_NO, A.WEB_LINK_ECR, A.WEB_LINK_ECR_NO, A.CEO_NAME_LOC, A.CEO_NAME_LOC_TEMP, A.ADDRESS_LOC, A.TEL_NO, A.FAX_NO, A.USER_NAME_LOC, A.PHONE_NUMBER, A.EMAIL, A.MOBILE_PHONE, -- A.KEP_DAMDANG, A.CONTRACT_DOC_YN, A.INFO_SP_TYPE, A.CM_CREDIT_STATUS, A.CREDIT_RATING, A.CREDIT_EXPIRE_DATE, A.ADD_DATE, A.CM_CMP_FLAG, A.CMP_CLOSE_NOTE, A.COM_CODE, A.MDM_NOTE, A.WIDUS, A.CREDIT_AGENT_CNT, A.ITM_MK1_NM, A.ITM_MK2_NM, A.ITM_MK3_NM, A.ITM_MK4_NM, A.ITM_MK5_NM, A.ITM_MK6_NM, A.ITM_MK7_NM, A.ITM_MK8_NM, A.ITM_MK9_NM, A.ITM_MK10_NM, A.ITM_MK1_AGENCY_NM, A.ITM_MK2_AGENCY_NM, A.ITM_MK3_AGENCY_NM, A.ITM_MK4_AGENCY_NM, A.ITM_MK5_AGENCY_NM, A.ITM_MK6_AGENCY_NM, A.ITM_MK7_AGENCY_NM, A.ITM_MK8_AGENCY_NM, A.ITM_MK9_AGENCY_NM, A.ITM_MK10_AGENCY_NM, A.PAY_TERMS, A.PAY_TERMS_NM, A.PAY_TYPE, A.PAY_TYPE_NM, SUM(A.ITEM_AMT) AS ITEM_AMT, SUM(A.AGENT_ITEM_AMT) AS AGENT_ITEM_AMT, ROUND(NVL((SUM(A.ITEM_AMT) - SUM(A.AGENT_ITEM_AMT)) / DECODE(SUM(A.AGENT_ITEM_AMT), 0, NULL, SUM(A.AGENT_ITEM_AMT)), 0) * 100, 2) AS SALE_PRFT_RATE, A.E_CONTRACT_TYPE AS E_CONTRACT_STATUS_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='ECST' AND FLAG='Y' AND CODE=E_CONTRACT_TYPE) AS E_CONTRACT_STATUS, A.EC_DOC_ID, A.E_CONTRACT_WMS_YN, A.EC_USER_EMAIL, A.EC_USER_NAME, TO_CHAR(TO_DATE(A.EC_DATE, 'YYYYMMDD'), 'YYYY/MM/DD') AS EC_DATE, TO_CHAR(ADD_MONTHS(TO_DATE(A.EC_DATE, 'YYYYMMDD'), 12), 'YYYY/MM/DD') AS EC_TO_DATE, (SELECT ADDRESS_LOC FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001') AS KEP_ADDRESS, (SELECT CEO_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001') AS KEP_CEO, TYPE_BEFORE_ONE, TYPE_BEFORE_TWO, REJECT_REASON, REJECT_USER_ID, SG_ID, A.KEP_DAMDANG
FROM ( SELECT CM.COM_NAME_LOC, DECODE(CM.MDM_CONFIRM_TYPE,'F','제재업체',(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M069' AND CODE = CM.STATUS)) AS CM_STATUS, CM.STATUS, CM.IRS_NO, '1' AS WEB_LINK_KCB, '1' AS WEB_LINK_KCB_NO, '2' AS WEB_LINK_ECR, '2' AS WEB_LINK_ECR_NO, CM.CEO_NAME_LOC, CM.CEO_NAME_LOC AS CEO_NAME_LOC_TEMP, CM.ADDRESS_LOC, CM.TEL_NO, CM.FAX_NO, CASE WHEN USR.STATUS = 'D' THEN '('|| '삭제' ||')' END||USR.USER_NAME_LOC AS USER_NAME_LOC, USR.PHONE_NUMBER, USR.EMAIL, USR.MOBILE_PHONE, -- INFO.KEP_DAMDANG_NM AS KEP_DAMDANG, DECODE(INFO.DEAL_CONTRACT_DOC_YN||INFO.DEAL_CONTRACT_DOC_YN||INFO.SEAL_CERT_DOC_YN|| INFO.BIZ_LICENCE_DOC_YN||INFO.BANKBOOK_COPY_YN||INFO.USING_SEAL_DOC_YN,'YYYYYY','Y','NNNNNN','N','보완필요') AS CONTRACT_DOC_YN, DECODE(INFO.SP_TYPE,'N','정규','T','임시','S','정규(특별계약)','E','계약제외') AS INFO_SP_TYPE, DECODE(CM.CREDIT_STATUS,'A','B-이상','B','등급미달','C','면제','N','미평가') CM_CREDIT_STATUS, CM.CREDIT_RATING, CM.CREDIT_EXPIRE_DATE, CM.ADD_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M041' AND CODE = CM.CMP_CLOSE_FLAG) AS CM_CMP_FLAG, CM.CMP_CLOSE_NOTE, CM.COM_CODE, CM.MDM_NOTE, NVL(DECODE(SUBSTR(CM.IRS_NO,5,2),'85',CM.CORP_REG_NO,CM.IRS_NO),CM.IRS_NO) AS WIDUS, DECODE((SELECT COUNT(*) FROM ICOMCOD3 WHERE TYPE = 'BTOS' AND CODE2 = CM.COM_CODE AND FLAG = 'C'),0,'N','Y') CREDIT_AGENT_CNT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK1) AS ITM_MK1_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK2) AS ITM_MK2_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK3) AS ITM_MK3_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK4) AS ITM_MK4_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK5) AS ITM_MK5_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK6) AS ITM_MK6_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK7) AS ITM_MK7_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK8) AS ITM_MK8_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK9) AS ITM_MK9_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M104' AND CODE=INFO.ITM_MK10) AS ITM_MK10_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK1_AGENCY_YN) AS ITM_MK1_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK2_AGENCY_YN) AS ITM_MK2_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK3_AGENCY_YN) AS ITM_MK3_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK4_AGENCY_YN) AS ITM_MK4_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK5_AGENCY_YN) AS ITM_MK5_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK6_AGENCY_YN) AS ITM_MK6_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK7_AGENCY_YN) AS ITM_MK7_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK8_AGENCY_YN) AS ITM_MK8_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK9_AGENCY_YN) AS ITM_MK9_AGENCY_NM, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M067' AND CODE=INFO.ITM_MK10_AGENCY_YN) AS ITM_MK10_AGENCY_NM, AN.PAY_TERMS, /* 지불조건 */ (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='SA01' AND CODE = AN.PAY_TERMS) AS PAY_TERMS_NM, AN.PAY_TYPE, /* 지급형태 */ (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='SA03' AND CODE = AN.PAY_TYPE) AS PAY_TYPE_NM, NVL(DS.ITEM_AMT, 0) AS ITEM_AMT, NVL(DS.AGENT_ITEM_AMT, 0) AS AGENT_ITEM_AMT, INFO.E_CONTRACT_TYPE, INFO.EC_DOC_ID, INFO.E_CONTRACT_FLAG AS E_CONTRACT_WMS_YN, INFO.EC_USER_EMAIL, INFO.EC_USER_NAME, INFO.EC_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = INFO.TYPE_BEFORE_ONE AND FLAG = 'Y') AS TYPE_BEFORE_ONE, /*전년 협력사유형*/ (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M202' AND CODE = INFO.TYPE_BEFORE_TWO AND FLAG = 'Y') AS TYPE_BEFORE_TWO, /* 전전년 협력사유형*/ DECODE(CM.STATUS, 'D', CM.REJECT_REASON, '') AS REJECT_REASON, /*삭제 사유*/ DECODE(CM.STATUS, 'D', DECODE(CM.REJECT_REASON, NULL, '' , CM.CHANGE_USER_ID), '') AS REJECT_USER_ID, /*삭제자*/ INFO.SG_ID AS SG_ID, (SELECT TEXT4 FROM ICOMCOD3 WHERE TYPE ='CMSM' AND CODE2 = '1' AND CODE1 = INFO.SG_ID) AS KEP_DAMDANG FROM ICOMCMPY CM, ICOMLUSR USR, SUPLINFO2 INFO, ACNTSUPL AN, DSS_BUYER_RESULT DS WHERE CM.COM_CODE = INFO.SUPPLIER(+) AND CM.COM_CODE = USR.COM_CODE(+) AND CM.COM_CODE = AN.SUPPLIER AND USR.USER_TYPE (+)= 'A'
AND USR.STATUS(+) = 'D'
AND USR.STATUS (+)!= 'D'
AND CM.BUSINESS_COND = 'S' AND CM.COM_CODE = DS.AGENT(+)
AND UPPER(CM.COM_NAME_LOC) LIKE '%' ||UPPER(#{st_com_name}) || '%'
AND CM.IRS_NO LIKE '%' || #{st_irs_no} || '%'
AND CM.CEO_NAME_LOC LIKE '%' || #{st_ceo_name} || '%'
AND CM.TEL_NO LIKE '%' || #{st_tel_no} || '%'
AND USR.MOBILE_PHONE LIKE '%' || #{st_mobile_phone} || '%'
AND USR.EMAIL LIKE '%' || #{st_email} || '%'
AND (SELECT TEXT4 FROM ICOMCOD3 WHERE TYPE ='CMSM' AND CODE2 = '1' AND CODE1 = INFO.SG_ID) LIKE '%' || #{st_kep_damdang_id} || '%'
AND CM.ADDRESS_LOC LIKE '%' || #{st_address_loc} || '%'
AND CM.MDM_CONFIRM_TYPE = #{st_supplier_status}
AND CM.STATUS IN ('C', 'R')
AND CM.STATUS = #{st_supplier_status}
AND INFO.SP_TYPE = #{st_sp_type}
AND CM.CREDIT_STATUS = #{st_credit_status}
AND CM.CREDIT_RATING = #{st_credit_rating}
AND INFO.DEAL_CONTRACT_DOC_YN||INFO.DEAL_CONTRACT_DOC_YN||INFO.SEAL_CERT_DOC_YN||INFO.BIZ_LICENCE_DOC_YN||INFO.BANKBOOK_COPY_YN||INFO.USING_SEAL_DOC_YN NOT IN ('YYYYYY','NNNNNN')
AND INFO.DEAL_CONTRACT_DOC_YN||INFO.DEAL_CONTRACT_DOC_YN||INFO.SEAL_CERT_DOC_YN||INFO.BIZ_LICENCE_DOC_YN||INFO.BANKBOOK_COPY_YN||INFO.USING_SEAL_DOC_YN = #{st_deal_contract_doc}
AND CM.CMP_CLOSE_FLAG = #{st_cmp_flag}
AND (INFO.ITM_MK1 = #{st_itm_mk_cd} OR INFO.ITM_MK2 = #{st_itm_mk_cd} OR INFO.ITM_MK3 = #{st_itm_mk_cd} OR INFO.ITM_MK4 = #{st_itm_mk_cd} OR INFO.ITM_MK5 = #{st_itm_mk_cd} OR INFO.ITM_MK6 = #{st_itm_mk_cd} OR INFO.ITM_MK7 = #{st_itm_mk_cd} OR INFO.ITM_MK8 = #{st_itm_mk_cd} OR INFO.ITM_MK9 = #{st_itm_mk_cd} OR INFO.ITM_MK10 = #{st_itm_mk_cd})
AND (INFO.ITMG1_CD = #{st_itmg_cd} OR INFO.ITMG2_CD = #{st_itmg_cd} OR INFO.ITMG3_CD = #{st_itmg_cd} OR INFO.ITMG4_CD = #{st_itmg_cd} OR INFO.ITMG5_CD = #{st_itmg_cd})
/* ORDER BY CM.CONFIRM_DATE||CM.CONFIRM_TIME */ ) A WHERE 1=1
AND A.E_CONTRACT_TYPE = 'F'
AND A.E_CONTRACT_TYPE != 'F'
GROUP BY A.COM_NAME_LOC, A.CM_STATUS, A.STATUS, A.IRS_NO, A.WEB_LINK_KCB, A.WEB_LINK_KCB_NO, A.WEB_LINK_ECR, A.WEB_LINK_ECR_NO, A.CEO_NAME_LOC, A.ADDRESS_LOC, A.TEL_NO, A.FAX_NO, A.USER_NAME_LOC, A.PHONE_NUMBER, A.EMAIL, A.MOBILE_PHONE, A.CONTRACT_DOC_YN, A.INFO_SP_TYPE, A.CM_CREDIT_STATUS, A.CREDIT_RATING, A.CREDIT_EXPIRE_DATE, A.ADD_DATE, A.CM_CMP_FLAG, A.CMP_CLOSE_NOTE, A.COM_CODE, A.MDM_NOTE, A.WIDUS, A.CREDIT_AGENT_CNT, A.ITM_MK1_NM, A.ITM_MK2_NM, A.ITM_MK3_NM, A.ITM_MK4_NM, A.ITM_MK5_NM, A.ITM_MK6_NM, A.ITM_MK7_NM, A.ITM_MK8_NM, A.ITM_MK9_NM, A.ITM_MK10_NM, A.ITM_MK1_AGENCY_NM, A.ITM_MK2_AGENCY_NM, A.ITM_MK3_AGENCY_NM, A.ITM_MK4_AGENCY_NM, A.ITM_MK5_AGENCY_NM, A.ITM_MK6_AGENCY_NM, A.ITM_MK7_AGENCY_NM, A.ITM_MK8_AGENCY_NM, A.ITM_MK9_AGENCY_NM, A.ITM_MK10_AGENCY_NM, A.PAY_TERMS, A.PAY_TERMS_NM, A.PAY_TYPE, A.PAY_TYPE_NM, A.E_CONTRACT_TYPE, A.EC_DOC_ID, A.E_CONTRACT_WMS_YN, A.EC_USER_EMAIL, A.EC_USER_NAME, A.EC_DATE, A.TYPE_BEFORE_ONE, A.TYPE_BEFORE_TWO, A.REJECT_REASON, A.REJECT_USER_ID, A.SG_ID, A.KEP_DAMDANG

/* selectMasterMdCpAgntcmpyExcelList */ SELECT CM.COM_NAME_LOC, CM.COM_CODE, CM.IRS_NO, CM.INDUSTRY_TYPE, CM.BUSINESS_ITEMS, CM.CEO_NAME_LOC, (SELECT TEXT4 FROM ICOMCOD3 WHERE TYPE ='CMSM' AND CODE2 = '1' AND INFO.SG_ID = CODE1) AS KEP_DAMDANG_NAME, CM.TEL_NO, CM.ZIP_CODE, CM.ADDRESS_LOC, AC.BANK_ACCOUNT_NO , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M005' AND CODE = AC.BANK_CD) AS BANK_NAME, AC.DEPOSITOR, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M110' AND CODE = INFO.BIZ_TYPE) AS BIZ_TYPE_TEXT, DECODE(CM.MDM_CONFIRM_TYPE,'F','제재업체',(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M069' AND CODE = CM.STATUS)) AS CM_STATUS, DECODE(INFO.E_CONTRACT_TYPE, 'F', '체결', '미체결') AS E_CONTRACT_FLAG FROM ICOMCMPY CM, SUPLINFO2 INFO, ACNTSUPL AC WHERE CM.COM_CODE = INFO.SUPPLIER AND CM.COM_CODE = AC.SUPPLIER AND CM.BUSINESS_COND = 'S'
AND CM.COM_NAME_LOC LIKE '%' || #{st_com_name} || '%'
AND (SELECT TEXT4 FROM ICOMCOD3 WHERE TYPE ='CMSM' AND CODE2 = '1' AND CODE1 = INFO.SG_ID) LIKE '%' || #{st_kep_damdang_id} || '%'
